    (g[k]||[]).forEach(x=>{const old=by.get(String(x&&x.name||'')); if(!old) return; Object.keys(old).forEach(f=>x[f]=old[f]); x.sourceType='dictionary_foundation'; x.source='dictmaster'; x.createdBy='dictmaster'; x._dictmaster=true;});
