    school: (state.school && typeof state.school === 'object') ? state.school : null,   // 学校模式：校长/老师 产出 + 各步重试/完成标记（随项目持久化）
    longMemory: state.longMemory || { uiOpen:false, foreshadow:[], lastAuditAt:0 },
