const SIZE_DEFAULT = { min:3000, max:5000 };

let polishMulti = true;

/* ===================== app11：严格校验 + 定向修复重试 ===================== */
const VALIDATION_FAILURE_CODES = new Set([
  'STRUCTURE_ERROR','COUNT_ERROR','SOURCE_ERROR','DIVERSITY_ERROR','QUALITY_ERROR','SEMANTIC_ERROR','MODEL_ERROR'
]);
function classifyValidationFailure(report, err){
  const code=String(report?.code||'').toUpperCase();
  const details=String(report?.details||err?.message||'');
  if(!report || report.ok===false && /截断|没有返回|空|timeout|network|余额|model|模型|429|5\d\d/i.test(details)) return {category:'MODEL_ERROR',code:code||'MODEL_OUTPUT_ERROR',field:'output',details};
  if(/COUNT|OPTION_COUNT|SINGLE_OPTION_COUNT|DIMENSIONS_COUNT/i.test(code)) return {category:'COUNT_ERROR',code,field:'count',details};
  if(/FOREIGN_DIMENSION|ORIGINAL_ANCHOR|SOURCE|STRATEGIC_DIMENSIONS/i.test(code)) return {category:'SOURCE_ERROR',code,field:'source',details};
  if(/DIVERSITY|DUPLICATE|FINGERPRINT/i.test(code)) return {category:'DIVERSITY_ERROR',code,field:'diversity',details};
  if(/QUALITY|CREATIVE_ADDITIONS|SCHEMA|FIELD|NAME_EMPTY|MISSING_/i.test(code)) return {category:'QUALITY_ERROR',code,field:'quality',details};
  if(/SEMANTIC|FAITHFUL|MEANING/i.test(code)) return {category:'SEMANTIC_ERROR',code,field:'semantic',details};
  return {category:'STRUCTURE_ERROR',code:code||'VALIDATION_FAILED',field:'structure',details};
}
function structuredValidationFailure(report, err){
  const c=classifyValidationFailure(report,err);
  const repairHint={
    STRUCTURE_ERROR:'只修复 JSON 结构、字段类型、必填字段；不要改动已经正确的故事内容。',
    COUNT_ERROR:'只修复数量要求；保持已有有效方案内容不变，不得用占位方案凑数。',
    SOURCE_ERROR:'只修复与第一阶段权威战略源的引用关系；不得新增或反写全局 strategicDimensions。',
    DIVERSITY_ERROR:'只拉开方案之间真正的战略差异；不得只换书名、人物名或措辞。',
    QUALITY_ERROR:'只补齐缺失或空白的必填质量字段；不得削弱已有内容。',
    SEMANTIC_ERROR:'只修复与原始构想/战略约束的语义偏离；保留已经成立的内容。',
    MODEL_ERROR:'重新完整输出满足合同的结果；不要解释失败原因，不要输出半成品。'
  }[c.category];
  return {ok:false,category:c.category,code:c.code,field:c.field,details:c.details,repairHint};
}
function recordValidationAttempt(kind, attempt, failure, passed){
  if(!Array.isArray(state.aiValidationHistory)) state.aiValidationHistory=[];
  state.aiValidationHistory.push({kind,attempt,passed:!!passed,category:failure?.category||null,code:failure?.code||null,field:failure?.field||null,details:String(failure?.details||'').slice(0,500),ts:Date.now()});
  state.aiValidationHistory=state.aiValidationHistory.slice(-20);
}
function compactTextForAI(v, max=6000){
  const t=String(v||'').trim();
  if(t.length<=max) return t;
  const head=Math.max(0,Math.floor(max*0.72));
  const tail=Math.max(0,max-head);
  return t.slice(0,head)+'\n…（中间内容已省略，仅用于控制上下文体积）…\n'+t.slice(-tail);
}
function estimateAITokens(v){ return Math.max(0,Math.ceil(String(v||'').length/2)); }
function rememberPolishFailure(raw, failure, meta, kind='ideaOptimization'){
  const text=String(raw||'');
  state.polishRawFallback=text;
  state.polishFailureTrace={
    kind:kind||'ideaOptimization',
    category:failure?.category||'MODEL_ERROR',
    code:failure?.code||'UNKNOWN',
    field:failure?.field||'output',
    details:String(failure?.details||'').slice(0,800),
    repairHint:String(failure?.repairHint||'').slice(0,500),
    responseChars:text.length,
    responseTokenEstimate:estimateAITokens(text),
    truncated:meta?.finishReason==='length' || /截断|truncated/i.test(String(failure?.details||'')),
    attempt:Number(meta?.attempt||0)+1,
    requestChars:Number(meta?.requestChars||0),
    requestTokenEstimate:Number(meta?.requestTokenEstimate||0),
    ts:Date.now()
  };
}
function buildTargetedRepairPrompt(kind, originalUser, raw, failure, ctx){
  const source=(kind==='ideaPolishStage2' || kind==='ideaOptimization') ? `\n【当前生成上下文】\n${JSON.stringify({originalAnchors:ctx?.originalAnchors||null,strategicDimensions:ctx?.strategicDimensions||[],diversityProfile:ctx?.diversityProfile||null,multi:!!ctx?.multi})}` : '';
  const prev=String(raw||'');
  const prevCompact=prev.length>30000 ? prev.slice(0,24000)+'\n…（上一版过长，已裁剪）…\n'+prev.slice(-6000) : prev;
  return `${originalUser}\n\n【定向修复任务】\n上一版输出未通过严格校验。你现在只允许修复失败项，不得降低任何验收标准，也不得静默省略字段。\n失败分类：${failure.category}\n失败代码：${failure.code}\n失败字段：${failure.field}\n失败详情：${failure.details}\n修复建议：${failure.repairHint}${source}\n\n【上一版输出（受控长度）】\n${prevCompact}\n\n【硬性要求】\n1. 保留上一版已经有效的内容；只修复失败字段或与其直接相关的部分。\n2. 必须重新输出完整、可解析的最终结果，不要输出解释、诊断、道歉或“已修复”。\n3. 不得通过降低数量、删字段、改成占位文本、换名字/措辞来规避校验。\n4. 不得伪造用户事实；战略维度必须动态且与方案一致；若为 ideaOptimization，必须严格按纯文本合同重新完整输出，不得输出JSON。`;
}
async function callValidatedWithRepair(kind, extra, callOpts, ctx, maxRepair=VALIDATION_RETRY_MAX){
  const system=getSystemPrompt(kind,extra)+globalCreativeConstraintBlock(kind);
  let user=buildAIPrompt(kind,extra);
  const initialUser=user;
  let raw=''; let lastFailure=null;
  for(let attempt=0; attempt<=maxRepair; attempt++){
    try{
      const result=await callDeepSeek(system,user,Object.assign({},callOpts||{}, {taskKey:kind, retry: kind==='ideaPolishStage2' ? 1 : undefined}));
      raw=String(unwrapAIResult(result)||'').trim();
      const requestChars=String(user||'').length + String(system||'').length;
      const requestTokenEstimate=estimateAITokens(user)+estimateAITokens(system);
      if(!raw){
        lastFailure=structuredValidationFailure({ok:false,code:'EMPTY_OUTPUT',details:'AI未返回内容'},null);
      }else if(result?.finishReason==='length'){
        lastFailure=structuredValidationFailure({ok:false,code:'OUTPUT_TRUNCATED',details:`AI返回在输出上限处被截断；响应约 ${raw.length.toLocaleString()} 字`},null);
      }else{
        const report=validateAIOutput(kind,raw,ctx);
        if(report && report.ok){
          recordValidationAttempt(kind,attempt, null,true);
          if(kind==='ideaPolishStage2' || kind==='ideaOptimization'){ state.polishRawFallback=''; state.polishFailureTrace={kind,category:null,code:null,field:null,details:'生成并通过严格校验',responseChars:raw.length,responseTokenEstimate:estimateAITokens(raw),truncated:false,attempt:attempt+1,requestChars,requestTokenEstimate,ts:Date.now()}; }
          return {raw,attempts:attempt};
        }
        lastFailure=structuredValidationFailure(report,null);
      }
      if(kind==='ideaPolishStage2' || kind==='ideaOptimization') rememberPolishFailure(raw,lastFailure,{attempt,requestChars,requestTokenEstimate,finishReason:result?.finishReason},kind);
    }catch(e){
      lastFailure=structuredValidationFailure({ok:false,code:'CALL_FAILED',details:e?.message||String(e)},e);
      if(kind==='ideaPolishStage2' || kind==='ideaOptimization') rememberPolishFailure(raw,lastFailure,{attempt,requestChars:String(user||'').length + String(system||'').length,requestTokenEstimate:estimateAITokens(user)+estimateAITokens(system)},kind);
    }
    recordValidationAttempt(kind,attempt,lastFailure,false);
    if(attempt>=maxRepair) break;
    // 修复请求只复用最初的紧凑任务上下文；不再把“上一轮修复Prompt”套娃进下一轮。
    user=buildTargetedRepairPrompt(kind,initialUser,raw,lastFailure,ctx);
  }
  const e=new Error(`${kind} 严格校验最终失败 [${lastFailure?.category||'MODEL_ERROR'}/${lastFailure?.code||'UNKNOWN'}]：${lastFailure?.details||'未知错误'}。${lastFailure?.repairHint||''}`);
  e.validationFailure=lastFailure; e.attempts=maxRepair+1;
  throw e;
}

async function generateOptimizationRaw(callOpts, ctx){
  const kind='ideaOptimization';
  const system=getSystemPrompt(kind,ctx)+globalCreativeConstraintBlock(kind);
  const user=buildAIPrompt(kind,ctx);
  const result=await callDeepSeek(system,user,Object.assign({},callOpts||{}, {taskKey:kind, retry: undefined}));
  const raw=String(unwrapAIResult(result)||'').trim();
  if(!raw) throw new Error('AI未返回内容');
  if(result?.finishReason==='length') addGenerationDiagnostic('ideaOptimization',{type:'RUNTIME_OUTPUT',code:'OUTPUT_TRUNCATED',details:'AI返回在输出上限处被截断；严格质检关闭，不触发验证重试。',blocking:false});
  return {raw,attempts:0,finishReason:result?.finishReason||null};
}

async function generateOptimizationConcept(btn, force){
  const idea=(state.idea||'').trim();
  if(!idea){ toast('请先输入故事构想'); return false; }
  const kept=Array.isArray(state.polishOptions)&&state.polishOptions.length;
  if(kept && !force){ if(!confirm(`已有 ${kept} 个优化方案，重新生成将覆盖当前批次。继续？`)) return false; }
  const multi=polishMulti===true;
  state.polishMode=multi?'multi':'single';
  state.strategyStage1Status='generating';
  state.strategyStage2Status='generating';
  state.polishStatus='generating';
  state.polishSelectedId=null; state.polishAdopted=null; state.canonicalStoryStrategy=null;
  state.polishOptions=[]; state.strategicDimensions=[]; state.strategicDiversityProfile=null; state.originalIdeaAnchors=null;
  state.polishDiagnosis=null; state.polishStrategies=[]; state.polishFailureTrace=null; state.polishRawFallback='';
  persist();
  const live=$('#btnOptimizationConcept'); if(live) busy(live,true,multi?'✨ 正在生成3—5个优化构想…':'✨ 正在生成优化构想…');
  markAIRunning('ideaOptimization'); markAIRunning('idea');
  try{
    const ctx={multi};
    const callOpts={temperature:resolveActiveSpec().ideaTemp,maxTokens:Math.max(4500,clampMaxTokens('polish'))};
    const strictQc=state.ideaOptimizationStrictQc===true;
    // 关闭严格质检：只做一次 AI 生成；不触发 validation/repair retry。
    // callDeepSeek 自身的网络层 retry 仍保留，不属于质检重试。
    const v=strictQc
      ? await callValidatedWithRepair('ideaOptimization',ctx,callOpts,ctx)
      : await generateOptimizationRaw(callOpts,ctx);
    state.polishRawFallback=String(v.raw||'').trim();
    const parsed=parseOptimizationPlainText(v.raw,multi);
    if(!parsed.ok){
      if(strictQc) throw new Error(parsed.error||'优化构想纯文本解析失败');
      addGenerationDiagnostic('ideaOptimization',{type:'STRUCTURE',code:'OPTIMIZATION_PARSE_PARTIAL',details:parsed.error||'优化构想纯文本解析失败；已保留原始AI输出，质检关闭不阻挡完成。',blocking:false});
      const rawText=String(v.raw||'').trim();
      state.polishOptions=rawText ? [{_id:'polish-'+Date.now(),name:'AI原始方案',text:rawText,optimizedIdea:rawText,_rawFallback:true}] : [];
      state.polishSelectedId=multi?null:(state.polishOptions[0]?state.polishOptions[0]._id:null);
      state.polishAdopted=multi?null:(state.polishOptions[0]?state.polishOptions[0].name:null);
      state.polishStatus=multi?'waiting_selection':'ready_single';
      state.strategyStage1Status='ready';
      state.strategyStage2Status='ready';
      markAIDone('ideaOptimization'); markAIDone('idea');
      persist(); refreshPolishUi(); queueGenerationFocus('#polishBox',120);
      toast('优化构想已生成：严格质检关闭，已保留AI原始结果');
      return true;
    }
    state.originalIdeaAnchors=parsed.analysis.originalAnchors;
    state.strategicDimensions=parsed.analysis.strategicDimensions;
    state.strategicDiversityProfile=parsed.analysis.diversityProfile;
    state.polishStrategyTrace={ts:Date.now(),originalAnchors:state.originalIdeaAnchors,strategicDimensions:state.strategicDimensions};
    showPolishResult(v.raw,multi);
    state.strategyStage1Status='ready';
    state.strategyStage2Status='ready';
    state.polishFailureTrace=null; state.polishRawFallback='';
    markAIDone('ideaOptimization'); markAIDone('idea');
    persist();
    toast(multi?`优化构想完成：已生成 ${state.polishOptions.length} 个方案`:'优化构想完成：已生成最终方案');
    playEventSound('polish_done');
    refreshPolishUi();
    queueGenerationFocus('#polishBox',120);
    return true;
  }catch(e){
    state.strategyStage1Status='error'; state.strategyStage2Status='error';
    addToFixQueue({kind:'ideaOptimization',error:e.message});
    toast('优化构想生成失败：'+e.message); reportSoundError('polish',e); persist(); refreshPolishUi(); queueGenerationFocus('#polishBox',120); return false;
  }finally{
    state.aiNetwork.running=(state.aiNetwork.running||[]).filter(k=>!['ideaOptimization','ideaStrategy','ideaPolishStage2','idea'].includes(k));
  }
}

