  const style=wsItems&&wsItems.length?wsItems.map(s=>`${s.name}：${s.note||''}${Array.isArray(s.tips)&&s.tips.length?`（写法：${s.tips.join('；')}）`:''}`).join('\n'):'（未额外锁定写作风格）';
  const bb=currentBookBeatCfg(), mb=currentBeatCfg(), cc=chapterCountVal();
  const parts=[];
