  const ov = document.createElement('div'); ov.id='dmpPanel'; ov.className='gs-overlay';
  const tabs = hist.map((h,i)=>`<button class="dm-tab" data-dm-tab="${i}" title="第 ${hist.length-i} 次">#${hist.length-i}</button>`).join('');
