      const m=parsePairs(detail); res.institutions.push({name, type:m['类型']||m['类别']||'', function:m['行业/职能']||m['职能']||m['行业']||'', audience:m['服务对象']||'', location:m['地点']||'', note:m['说明']||m['备注']||detail}); continue;
